use rstyle_core::{config::Config, facts::FnFacts};
use serde_json::Value;
fn main() {
    let input: Value = serde_json::from_reader(std::io::stdin()).unwrap();
    let config: Config = serde_json::from_value(input["config"].clone()).unwrap();
    let facts: Vec<FnFacts> = serde_json::from_value(input["facts"].clone()).unwrap();
    let report = rstyle_core::evaluate(facts, &config).unwrap();
    serde_json::to_writer(std::io::stdout(), &report).unwrap();
}
